def _french_typography(value):
    """No-break (narrow) spaces before : ; ? ! % and inside « », so they never wrap."""

    if isinstance(value, str):
        for plain, spaced in ((" :", " :"), (" ;", " ;"), (" ?", " ?"), (" !", " !"),
                              (" %", " %"), ("« ", "« "), (" »", " »")):
            value = value.replace(plain, spaced)
        return value
    if isinstance(value, dict):
        return {key: _french_typography(item) for key, item in value.items()}
    if isinstance(value, list):
        return [_french_typography(item) for item in value]
    if isinstance(value, tuple):
        return tuple(_french_typography(item) for item in value)
    return value


TEXT["fr"] = _french_typography(TEXT["fr"])
